script:
export const meta = {
  name: 'v5-k-mapping',
  description: 'Map all 4,647 human verifiers to K1-K5 rubric questions (from the refined docx catalog); agents write per-task mapping files',
  phases: [{ title: 'Map', detail: '20 agents x 5 tasks' }],
}

const SCR = '/private/tmp/claude-501/-Users-dhiren-Downloads-Deccan/aa9e6dfc-7579-493e-a3a8-45be309ed406/scratchpad/kmap'
const pad = n => String(n).padStart(2, '0')
const IDS = []
for (let i = 1; i <= 30; i++) IDS.push('PHOTO-' + pad(i))
for (let i = 1; i <= 15; i++) IDS.push('VECTOR-' + pad(i))
for (let i = 1; i <= 35; i++) IDS.push('LAYOUT-' + pad(i))
for (let i = 1; i <= 20; i++) IDS.push('MOTION-' + pad(i))
const BATCHES = []
for (let i = 0; i < IDS.length; i += 5) BATCHES.push(IDS.slice(i, i + 5))

const SCHEMA = {
  type: 'object',
  properties: {
    files_written: { type: 'array', items: { type: 'string' } },
    mapped_total: { type: 'number' },
    notes: { type: 'string' },
  },
  required: ['files_written', 'mapped_total'],
}

function prompt(ids) {
  return `You are mapping human verifier checks of a creative-AI benchmark to the K1-K5 capability rubric, so the review page can group them section-wise with zero ambiguity.

STEP 1 — Read the catalog: ${SCR}/k_catalog.json. It defines the capabilities and their question ids:
- K1 Instruction adherence: K1_Q1 content completeness, K1_Q2 specification accuracy, K1_Q3 constraint compliance, K1_Q4 deliverable completeness, K1_Q5 critical failure.
- K2 Asset utilization & fidelity: K2_Q1 asset selection, K2_Q2 asset preservation, K2_Q3 brand-system compliance, K2_Q4 identity fidelity, K2_Q5 asset appropriateness.
- K3 Compositional craft: family-specific ids (use ONLY the checklist for the task's family, e.g. K3_PHO_C3 mask & edge for a Photo task).
- K4 Creative quality: K4_Q1 concept strength, K4_Q2 brief relevance, K4_Q3 distinctiveness.
- K5 Communication effectiveness: K5_Q1 primary message, K5_Q2 information hierarchy, K5_Q3 required details, K5_Q4 audience, K5_Q5 miscommunication.

STEP 2 — For each task id in ${JSON.stringify(ids)}: Read ${SCR}/human/<TASK_ID>.json ({task_id, family, checks:[{check_id, text, artifact, file, evidence}]}). Assign EVERY check exactly ONE question id, choosing the single best fit by what the check actually verifies:
- Exact required text/values/records present or reading exactly (names, prices, dates, claims, copy) -> K1_Q1 (required content present) or K1_Q2 (a measurable spec: size, count, duration, format, colour value).
- Obeying a must/must-not/preservation/production rule (do-not-alter, keep silent, no invented claims, clearance rules) -> K1_Q3.
- All requested files/variants delivered (set completeness across outputs) -> K1_Q4.
- A check whose failure alone makes the commission unusable (wrong allergen, wrong legal line, unplayable film) -> K1_Q5 ONLY if the check is explicitly framed that way; otherwise prefer the specific question.
- Uses the correct supplied asset / shows the product from a named source photo -> K2_Q1. Locked asset unchanged / not regenerated -> K2_Q2. Brand fonts, colours, logo usage correct -> K2_Q3. Person/product/logo still recognizably the same -> K2_Q4. Asset used in the right role/context -> K2_Q5.
- Craft/finish quality (cut edges, halos, retouch naturalness, grade cohesion, grid, spacing, overflow, pacing, sync) -> the matching K3_<FAM> item for THIS task's family; if no family item fits, fall back to the closest K1/K5 question.
- Whether the piece communicates (main message identifiable, hierarchy reads first, supporting details recoverable, audience fit, nothing misleading) -> K5_Q1..Q5.
- Concept/originality/genericness -> K4_Q1..Q3 (rare).
Never invent ids. Use each task's OWN family for K3 ids.

STEP 3 — For each task, Write the file ${SCR}/out/<TASK_ID>.map.json containing exactly: {"task_id":"<TASK_ID>","mappings":[{"check_id":"...","k_id":"..."}]} with one entry per check (complete coverage — count them). Then return the structured object listing the files you wrote and the total mappings. Do NOT return the mappings inline.`
}

phase('Map')
const results = await parallel(BATCHES.map((ids) => () =>
  agent(prompt(ids), { label: `map:${ids[0]}..${ids[ids.length-1]}`, phase: 'Map', agentType: 'general-purpose', schema: SCHEMA })
))

const ok = results.filter(Boolean)
return { batches: results.length, null_batches: results.length - ok.length, mapped_total: ok.reduce((s, r) => s + (r.mapped_total || 0), 0), files: ok.reduce((s, r) => s + ((r.files_written || []).length), 0) }
